PALS_DOUBLE=(15543, 'aade15ab4c04b0d701cbfb1eb1799d4608f36c32cb8ec5529992c8cf4d5ee83d')

def _pin(data):return len(data),hashlib.sha256(data).hexdigest()
def _need(ok,message):
    if not ok:raise ValueError(message)

def _forward(source):
    _need(type(source)is bytes and _pin(source)==NORMAL,'actual fixed A NORMAL source differs')
    result=source
    for at,newat,old,new,name in reversed(EDITS):
        _need(source[at:at+len(old)]==old,'PALS input anchor differs '+name)
        result=result[:at]+new+result[at+len(old):]
    _need(_pin(result)==AFTER,'PALS source result differs')
    return result

def _inverse(result):
    _need(type(result)is bytes and _pin(result)==AFTER,'fixed PALS source differs')
    source=result
    for at,newat,old,new,name in reversed(EDITS):
        _need(result[newat:newat+len(new)]==new,'PALS inverse anchor differs '+name)
        source=source[:newat]+old+source[newat+len(new):]
    _need(_pin(source)==NORMAL,'PALS inverse NORMAL differs')
    return source

def transform_source(source,previous):
    _need(type(source)is bytes and _pin(source)==BEFORE,'current default A source differs')
    normal,normal_metadata=previous(source)
    result=_forward(normal)
    _need(_inverse(result)==normal,'PALS entire inverse differs')
    for at,newat,length,digest in GAPS:
        gap=normal[at:at+length]
        _need(result[newat:newat+length]==gap and hashlib.sha256(gap).hexdigest()==digest,'PALS protected complement differs')
    _need(result.count(b'if(w==qr)V(I,U);')==1,'helper TT payload fence differs')
    return result,{'policy':POLICY,'normal_source':normal_metadata,'regions':len(EDITS),'protected_gaps':len(GAPS),
        'source_bytes':AFTER[0],'source_sha256':AFTER[1],'full_inverse':True,'workers':2,'tt_bits':18,'ply':128,
        'hint_and_completed_NORMAL_reuse':True,'counter_is_root_bound':False,'same_first_unrestricted_Repair':True,
        'challenged_reply_rechecked':True,'original_deadline_and_round_drain':True,'runtime_qualified':False,'external_reads':0}

def transform_literal(expression,previous):
    _need(type(expression)is str and _pin(expression.encode())==PALS_SINGLE,'PALS raw-single literal differs')
    q=chr(39)*3;d=chr(34)*3
    _need(expression[:5]=='br'+q and expression[-3:]==q,'PALS raw-single delimiters differ')
    normal=_inverse(expression[5:-3].encode('ascii'))
    prior='br'+q+normal.decode('ascii')+q
    guarded=previous(prior)
    _need(ast.literal_eval(guarded)==normal and guarded[:5]=='br'+d and guarded[-3:]==d,'actual NORMAL/older literal guards differ')
    selected='br'+d+_forward(ast.literal_eval(guarded)).decode('ascii')+d
    _need(_pin(selected.encode())==PALS_DOUBLE and ast.literal_eval(selected)==expression[5:-3].encode('ascii'),'PALS literal forward/inverse differs')
    return selected
